// cases.js -- a review of the library prompt (LIBRARY_CATALOG) and of SUITE_CHAT's new KEEPS how-to pattern
// (wip-2026-11-24-library, 0035cea), written by a reviewer who did not write the change. Each case says what is
// RIGHT for its input; replay.js says whether Lantern does it.
//
// part "keeps"  input: a question. Run with the usual prompt (Prompt size: Automatic) through Chat's lesson providers
//               in their own order (Lantern.chatContext, after the safety rule Lantern.ai.guard), as ASSIST_CHAT does.
//               Seen: "(guard)", the key of the FIRST passage the first provider gives, or "(none)".
//               expect: the keys acceptable as that first passage; "(none)" in the list means giving nothing is also
//               right; [] means nothing must be given (a guard answer counts as nothing given).
//               never (optional): keys that must not be among any passage given.
// part "open"   input: a model's reply. Seen: the OPEN command's test(reply) with the library prompt (or `mode`).
//               expect: the shelf string it must read, or null; a list means any of them is right.
// part "header" input: a question. Seen: Lantern.catalog.header(route(q)) with the library prompt.
//               A claim is "This question is on shelf X" (sure), "most likely on shelf X" (likely) or "about Lantern
//               itself (shelf X)". A suggestion is "may be on shelf X ... OPEN X".
//               expect: the shelves acceptable for a claim (and for a suggestion), or "no-claim" (no claim allowed;
//               a suggestion still is). Making no claim is always allowed unless mustClaim is set.
// part "prompt" input: {q, check, ...}. check:
//               "chat-body"     the library CHAT.buildSystem(q) is the fixed start, the header, then the short
//                               prompt whole but for its first lines about who the model is
//               "assist-body"   the same for Lantern.assist.buildPrompt(q, match(q))
//               "assist-offers" Assist's library prompt neither asks for OPEN nor says lessons or a catalog come
//                               with the question (Assist runs no OPEN and sends no lessons)
//               "consistent"    in Chat's library prompt the header says "its lessons come with the question" exactly
//                               when Chat's providers give lessons, and never "no lesson it is sure of" when they do
//               "open-run"      what OPEN <shelf> sends for q: its first lesson is one of `first` ("(none)": nothing)
//               expect: true (the check holds).
// severity: how much it matters when Lantern does not do what the case says.
"use strict";
function K(id, q, expect, severity, why, never) { var c = { id: "keeps-" + id, part: "keeps", input: q, expect: expect, severity: severity, why: why }; if (never) c.never = never; return c; }
function O(id, reply, expect, severity, why, mode) { var c = { id: "open-" + id, part: "open", input: reply, expect: expect, severity: severity, why: why }; if (mode) c.mode = mode; return c; }
function H(id, q, expect, severity, why, extra) { var c = { id: "header-" + id, part: "header", input: q, expect: expect, severity: severity, why: why }; if (extra) for (var k in extra) c[k] = extra[k]; return c; }
function P(id, input, severity, why) { return { id: "prompt-" + id, part: "prompt", input: input, expect: true, severity: severity, why: why }; }
var N = "(none)", G = "(guard)";
var FOODKEEP = ["food_cook", "food_safe"];

